-- BlockDrive for the BlockOS App Store.
-- Generated by tools/build.py from src/blockdrive-package.lua. The App Store installs one file
-- per app, so the BlockCloud client library is bundled here: on launch it is written to
-- /blockos/lib/cloud (unless a newer copy is already there) and then the app runs.

local Version = "@VERSION@"
local Files = {}
--@FILES@

local Config = BlockOS.Require("config")
local Updater = BlockOS.Require("updater")

local Marker = "/blockos/lib/cloud/version.txt"
local Installed = Config.ReadText(Marker)
Installed = Installed and Installed:gsub("%s", "")

-- A newer library (from the BlockDrive installer or a later package) is left alone.
if (not Installed or Updater.Compare(Installed, Version) <= 0) then
	local Changed = false
	for Path, Source in pairs(Files) do
		if (Path:find("^blockos/lib/cloud/") or Path == "blockos/bin/bdrive.lua") then
			if (Config.ReadText("/" .. Path) ~= Source) then
				Config.WriteText("/" .. Path, Source)
				Changed = true
			end
		end
	end
	if (Changed or Installed ~= Version) then Config.WriteText(Marker, Version) end
end

local App, Err = load(Files["blockos/apps/blockdrive/main.lua"], "@/blockos/apps/blockdrive/main.lua", "t",
	setmetatable({ BlockDrivePackage = { Version = Version } }, { __index = _ENV }))
if (not App) then error(Err, 0) end
return App(...)
